// Liveness: 只检查进程是否活跃
http.HandleFunc("/livez", func(w http.ResponseWriter, r *http.Request) {
    w.WriteHeader(http.StatusOK)
    w.Write([]byte("alive"))
})

// Readiness: 检查依赖和服务能力
http.HandleFunc("/readyz", func(w http.ResponseWriter, r *http.Request) {
    if err := db.Ping(); err != nil {
        w.WriteHeader(http.StatusServiceUnavailable)
        w.Write([]byte("database unavailable"))
        return
    }
    if err := redisClient.Ping(); err != nil {
        w.WriteHeader(http.StatusServiceUnavailable)
        w.Write([]byte("redis unavailable"))
        return
    }
    w.WriteHeader(http.StatusOK)
    w.Write([]byte("ready"))
})

// 不要在健康检查中执行重负载操作
http.HandleFunc("/ready", func(w http.ResponseWriter, r *http.Request) {
    // ❌ 错误：复杂查询
    // rows, err := db.Query("SELECT COUNT(*) FROM large_table WHERE status = 'active'")

    // ✅ 正确：轻量级连接测试
    if err := db.Ping(); err != nil {
        w.WriteHeader(http.StatusServiceUnavailable)
        return
    }
    w.WriteHeader(http.StatusOK)
})

const express = require('express');
const app = express();

// Startup probe: 检查应用是否完成初始化
let isStarted = false;
app.get('/healthz/startup', (req, res) => {
  if (isStarted) {
    res.status(200).send('started');
  } else {
    res.status(503).send('not started');
  }
});

// Liveness probe: 仅检查进程是否响应
app.get('/healthz/liveness', (req, res) => {
  res.status(200).send('alive');
});

// Readiness probe: 检查依赖服务
app.get('/healthz/readiness', async (req, res) => {
  try {
    // 检查数据库连接
    await dbPool.query('SELECT 1');

    // 检查 Redis 连接
    await redisClient.ping();

    res.status(200).json({ status: 'ready' });
  } catch (error) {
    console.error('Readiness check failed:', error);
    res.status(503).json({ status: 'not ready', error: error.message });
  }
});

// 应用启动完成后标记为已启动
app.listen(3000, () => {
  console.log('Server started on port 3000');
  isStarted = true;  // 标记启动完成
});

import (
    "google.golang.org/grpc/health"
    "google.golang.org/grpc/health/grpc_health_v1"
)

func main() {
    server := grpc.NewServer()

    // 注册 gRPC 健康检查服务
    healthServer := health.NewServer()
    grpc_health_v1.RegisterHealthServer(server, healthServer)

    // 启动时标记为 NOT_SERVING
    healthServer.SetServingStatus("", grpc_health_v1.HealthCheckResponse_NOT_SERVING)

    // 应用初始化...
    initDatabase()
    initCache()

    // 初始化完成后标记为 SERVING
    healthServer.SetServingStatus("", grpc_health_v1.HealthCheckResponse_SERVING)

    server.Serve(listener)
}
